parameters.text:
=Company: {{ $json.company }}
Domain: {{ $json.domain || 'unknown' }}

Research this company's hiring over the last {{ $('Research settings').first().json.lookback_days }} days and return the brief.

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "signal_score": {
      "type": "integer",
      "minimum": 0,
      "maximum": 10
    },
    "summary": {
      "type": "string",
      "description": "One paragraph: what they are hiring for and why it matters for us"
    },
    "open_roles": {
      "type": "integer",
      "description": "Total matching postings reported by the search"
    },
    "top_teams": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "top_locations": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "example_links": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "maxItems": 3
    }
  },
  "required": [
    "signal_score",
    "summary",
    "open_roles",
    "top_teams",
    "top_locations",
    "example_links"
  ]
}

parameters.text:
